Object.assign(SNIP,{"l25arr": "int a[5] = {3, 1, 4, 1, 5};\nint* p = a;       // tên mảng = địa chỉ phần tử đầu, giống &a[0]\n*(p + 2);         // 4   (p + 2 là địa chỉ a[2])\np[2];             // 4   (viết gọn của *(p + 2))\np++;              // p trỏ tới a[1]\n(a + 5) - a;      // 5   (hiệu hai con trỏ = số phần tử ở giữa)", "l25func": "void hoanVi(int* a, int* b) {     // nhận ĐỊA CHỈ của hai biến\n    int t = *a;\n    *a = *b;\n    *b = t;\n}\nint tong(const int* a, int n) {   // const: chỉ đọc qua con trỏ, không sửa\n    int s = 0;\n    for (int i = 0; i < n; i++) s += a[i];\n    return s;\n}\n// gọi: hoanVi(&x, &y);   tong(a, 5);", "l25decl": "int x = 10;\nint* p = &x;      // p giữ địa chỉ của x (\"p trỏ tới x\")\ncout << p;        // in địa chỉ, ví dụ 0x7ffd7ffd5c4c\ncout << *p;       // 10: giá trị tại địa chỉ p đang giữ\n*p = 25;          // ghi qua con trỏ: x thành 25\nint* q = nullptr; // con trỏ chưa trỏ tới đâu"});PRESET_NOTES["l25"]={"Ví dụ: Địa chỉ và kích thước của biến": "Mỗi biến nằm ở một địa chỉ riêng; khung Hình động ghi địa chỉ dưới mỗi ô. Biến khai báo sau nằm ở địa chỉ thấp hơn: stack lớn dần về phía địa chỉ nhỏ. Địa chỉ in ra trên máy thật sẽ khác mỗi lần chạy.", "Ví dụ: Đọc và ghi qua con trỏ": "p = &x làm mũi tên chỉ vào x, nên *p = 20 sửa x. Sau p = &y, mũi tên chuyển sang y: cùng câu lệnh *p = ... giờ sửa y. Đổi p là đổi chỗ trỏ; đổi *p là đổi biến được trỏ.", "Ví dụ: Duyệt mảng bằng con trỏ": "p bắt đầu ở a (địa chỉ a[0]); mỗi p++ dịch sang phần tử kế tiếp, tức 4 byte với int. Vòng dừng khi p tới a + 5, vị trí ngay sau phần tử cuối. q[1] là *(q + 1), tức a[3]; q - a là số phần tử giữa hai con trỏ.", "Ví dụ: Hoán vị bằng con trỏ": "Khi hoanVi đang chạy, khung Hình động có hai tầng: main (x, y) và hoanVi (a, b, t). Mũi tên từ a và b chỉ ngược lên x và y của main: hàm sửa đúng biến của nơi gọi dù chúng không thuộc hàm.", "Ví dụ: Mảng truyền vào hàm là con trỏ": "nhanDoi nhận địa chỉ phần tử đầu nên sửa thẳng mảng của main. tong(a + 1, 2) bắt đầu từ a[1] và chỉ tính 2 phần tử: con trỏ cho phép truyền một đoạn con của mảng. const int* bảo đảm tong không sửa mảng.", "Lỗi: dùng con trỏ chưa khởi tạo": "p chưa được gán nên chứa một địa chỉ rác; g++ cảnh báo 'p' is used uninitialized. Ghi vào đó là hành vi không xác định: thường Segmentation fault. Luôn khởi tạo: int* p = nullptr; hoặc int* p = &x;.", "Lỗi: dùng *p khi p là nullptr": "Điều kiện sai nên p vẫn là nullptr, không trỏ tới đâu. Hệ điều hành chặn truy cập địa chỉ 0 và dừng chương trình. Sửa: if (p != nullptr) cout << *p; trước khi dùng."};EX_HINTS["l25"]=[["Giống hoán vị hai số: cần một biến tạm t để giữ giá trị cũ của *a trước khi bị ghi đè.", "Thứ tự: t = *a; *a = *b; *b = *c; *c = t;"], ["Một hàm chỉ return được một giá trị; muốn trả hai kết quả, cho hàm ghi vào hai biến của main qua con trỏ.", "Khởi tạo *mn = *mx = a[0] (không dùng 0: dãy toàn số âm sẽ sai)."], ["So sánh hai con trỏ cùng một mảng bằng <: l < r nghĩa là l còn đứng trước r.", "Mỗi vòng đổi chỗ hai phần tử ở hai đầu, sau đó l++ và r-- để thu hẹp đoạn còn lại."]];
/* ===================== BÀI 25 · Địa chỉ và con trỏ ===================== */
/* Bài 25 · Địa chỉ và con trỏ
   Sinh bởi công cụ soạn bài: ví dụ cho trình mô phỏng (kèm hình động), bài tập chấm tự động.
   Trắc nghiệm ở quiz.json, gợi ý ở hints.json, lời giải ở solutions/ (nội dung bảo vệ). */
const P25=[{label:"Ví dụ: Địa chỉ và kích thước của biến",input:"",code:"#include <iostream>\nusing namespace std;\n\nint main() {\n    int x = 10;\n    double d = 2.5;\n    char c = 'A';\n    cout << \"x = \" << x << \", o dia chi \" << &x << \", \" << sizeof(x) << \" byte\\n\";\n    cout << \"d = \" << d << \", o dia chi \" << &d << \", \" << sizeof(d) << \" byte\\n\";\n    cout << \"c chiem \" << sizeof(c) << \" byte\\n\";\n    return 0;\n}",viz:[{type:"mem"}]},{label:"Ví dụ: Đọc và ghi qua con trỏ",input:"",code:"#include <iostream>\nusing namespace std;\n\nint main() {\n    int x = 10, y = 7;\n    int* p = &x;\n    cout << *p << \"\\n\";\n    *p = 20;\n    cout << \"x = \" << x << \"\\n\";\n    p = &y;\n    *p = *p + 1;\n    cout << \"x = \" << x << \", y = \" << y << \"\\n\";\n    return 0;\n}",viz:[{type:"mem"}]},{label:"Ví dụ: Duyệt mảng bằng con trỏ",input:"",code:"#include <iostream>\nusing namespace std;\n\nint main() {\n    int a[5] = {3, 1, 4, 1, 5};\n    int tong = 0;\n    for (int* p = a; p < a + 5; p++) {\n        tong += *p;\n    }\n    cout << \"Tong = \" << tong << \"\\n\";\n    int* q = a + 2;\n    cout << *q << \" \" << q[1] << \" \" << q - a << \"\\n\";\n    return 0;\n}",viz:[{type:"mem"}]},{label:"Ví dụ: Hoán vị bằng con trỏ",input:"",code:"#include <iostream>\nusing namespace std;\n\nvoid hoanVi(int* a, int* b) {\n    int t = *a;\n    *a = *b;\n    *b = t;\n}\n\nint main() {\n    int x = 3, y = 8;\n    hoanVi(&x, &y);\n    cout << \"x = \" << x << \", y = \" << y << \"\\n\";\n    return 0;\n}",viz:[{type:"mem"}]},{label:"Ví dụ: Mảng truyền vào hàm là con trỏ",input:"",code:"#include <iostream>\nusing namespace std;\n\nint tong(const int* a, int n) {\n    int s = 0;\n    for (int i = 0; i < n; i++) s += a[i];\n    return s;\n}\n\nvoid nhanDoi(int* a, int n) {\n    for (int i = 0; i < n; i++) a[i] *= 2;\n}\n\nint main() {\n    int a[4] = {1, 2, 3, 4};\n    nhanDoi(a, 4);\n    cout << tong(a, 4) << \" \" << a[0] << \"\\n\";\n    cout << tong(a + 1, 2) << \"\\n\";\n    return 0;\n}",viz:[{type:"mem"}]},{label:"Lỗi: dùng con trỏ chưa khởi tạo",input:"",code:"#include <iostream>\nusing namespace std;\n\nint main() {\n    int* p;\n    *p = 5;\n    cout << *p << \"\\n\";\n    return 0;\n}",viz:[{type:"mem"}]},{label:"Lỗi: dùng *p khi p là nullptr",input:"",code:"#include <iostream>\nusing namespace std;\n\nint main() {\n    int* p = nullptr;\n    int x = 4;\n    if (x > 5) p = &x;\n    cout << *p << \"\\n\";\n    return 0;\n}",viz:[{type:"mem"}]}];
const sim25=makeSim2(document.getElementById("sim-l25"),{id:"s25",presets:P25});
makeEx2(document.getElementById("ex-l25"),sim25,[{t:"Xoay vòng ba số",d:"Nhập ba số nguyên x, y, z. Viết hàm <code>void xoay(int* a, int* b, int* c)<\/code> dời giá trị: a nhận giá trị của b, b nhận của c, c nhận giá trị cũ của a. Trong main gọi <code>xoay(&amp;x, &amp;y, &amp;z)<\/code> rồi in x y z.",tests:[{in:"1 2 3",out:"2 3 1"},{in:"5 5 7",out:"5 7 5"},{in:"-1 0 9",out:"0 9 -1"},{in:"100 200 300",out:"200 300 100"}],start:"#include <iostream>\nusing namespace std;\n\nvoid xoay(int* a, int* b, int* c) {\n    // dùng *a, *b, *c để đọc và sửa ba biến của main\n}\n\nint main() {\n    int x, y, z;\n    cin >> x >> y >> z;\n    xoay(&x, &y, &z);\n    cout << x << \" \" << y << \" \" << z << \"\\n\";\n    return 0;\n}",need:/void\s+xoay\s*\(\s*int\s*\*\s*\w+\s*,\s*int\s*\*\s*\w+\s*,\s*int\s*\*\s*\w+\s*\)[\s\S]*xoay\s*\(\s*&/,needMsg:"Hãy giữ hàm void xoay(int* a, int* b, int* c) và gọi bằng địa chỉ: xoay(&x, &y, &z)."},{t:"Nhỏ nhất và lớn nhất qua con trỏ",d:"Nhập n (1 ≤ n ≤ 1000) rồi n số nguyên. Viết hàm <code>void minMax(const int* a, int n, int* mn, int* mx)<\/code> ghi số nhỏ nhất vào <code>*mn<\/code>, lớn nhất vào <code>*mx<\/code>. In hai số đó cách nhau một dấu cách.",tests:[{in:"5\n3 9 -2 7 4",out:"-2 9"},{in:"1\n6",out:"6 6"},{in:"4\n-5 -1 -9 -3",out:"-9 -1"},{in:"6\n2 2 2 2 2 2",out:"2 2"}],start:"#include <iostream>\nusing namespace std;\n\nvoid minMax(const int* a, int n, int* mn, int* mx) {\n    // gán *mn, *mx ban đầu bằng a[0], rồi duyệt phần còn lại\n}\n\nint main() {\n    int n;\n    cin >> n;\n    int a[1000];\n    for (int i = 0; i < n; i++) cin >> a[i];\n    int nho, lon;\n    minMax(a, n, &nho, &lon);\n    cout << nho << \" \" << lon << \"\\n\";\n    return 0;\n}",need:/void\s+minMax\s*\(\s*const\s+int\s*\*\s*\w+\s*,\s*int\s+\w+\s*,\s*int\s*\*\s*\w+\s*,\s*int\s*\*\s*\w+\s*\)/,needMsg:"Hãy giữ đúng hàm void minMax(const int* a, int n, int* mn, int* mx)."},{t:"Đảo ngược mảng bằng hai con trỏ",d:"Nhập n (1 ≤ n ≤ 1000) rồi n số nguyên. Đảo ngược mảng tại chỗ bằng hai con trỏ: <code>int* l = a<\/code> ở đầu, <code>int* r = a + n - 1<\/code> ở cuối; đổi chỗ <code>*l<\/code>, <code>*r<\/code> rồi đưa hai con trỏ lại gần nhau. In mảng sau khi đảo.",tests:[{in:"5\n1 2 3 4 5",out:"5 4 3 2 1"},{in:"1\n7",out:"7"},{in:"4\n10 20 30 40",out:"40 30 20 10"},{in:"6\n-1 0 5 5 0 -1",out:"-1 0 5 5 0 -1"}],start:"#include <iostream>\nusing namespace std;\n\nint main() {\n    int n;\n    cin >> n;\n    int a[1000];\n    for (int i = 0; i < n; i++) cin >> a[i];\n    int* l = a;\n    int* r = a + n - 1;\n    // khi l còn đứng trước r: đổi chỗ *l và *r, rồi l++, r--\n    for (int i = 0; i < n; i++) cout << a[i] << \" \";\n    cout << \"\\n\";\n    return 0;\n}",need:/^(?![\s\S]*\breverse\s*\()[\s\S]*\*\s*l[\s\S]*\*\s*r/,needMsg:"Hãy đảo bằng hai con trỏ l, r (đổi chỗ *l và *r), không dùng reverse."}]);

makeQuiz("quiz25","score25",[{"q": "Sau <code>int x = 5; int* p = &amp;x; *p = 8;<\/code> thì x bằng bao nhiêu?", "o": ["5", "8", "Địa chỉ của x", "Lỗi biên dịch"], "a": 1, "e": "p giữ địa chỉ của x nên *p chính là x: gán *p = 8 làm x thành 8."}, {"q": "<code>int a[4] = {1, 2, 3, 4}; int* p = a + 1;<\/code> Giá trị của <code>*(p + 2)<\/code>?", "o": ["2", "3", "4", "Ngoài mảng"], "a": 2, "e": "p trỏ tới a[1]; p + 2 trỏ tới a[3], giá trị 4."}, {"q": "Khai báo nào tạo ra HAI con trỏ?", "o": ["<code>int* p, q;<\/code>", "<code>int *p, *q;<\/code>", "<code>int* (p, q);<\/code>", "Cả ba"], "a": 1, "e": "Dấu * gắn với từng tên: int* p, q; chỉ làm p là con trỏ, q là int thường."}, {"q": "<code>int* p = nullptr;<\/code> rồi chạy <code>cout &lt;&lt; *p;<\/code> thì sao?", "o": ["In ra 0", "In ra nullptr", "Lỗi biên dịch", "Chương trình bị dừng khi chạy (Segmentation fault)"], "a": 3, "e": "Cú pháp hợp lệ nên vẫn biên dịch được, nhưng nullptr không trỏ tới đâu: hệ điều hành chặn truy cập và dừng chương trình."}]);

